// Hashtag pool by region. Each run picks a random mix across ALL regions.
const POOL = {
  North:   ['delhifruits','gurgaonfruits','noidafruits','lucknowfruits','jaipurfruits','chandigarhfruits','ludhianafruits','dehradunfruits','kanpurfruits','faridabadfruits'],
  West:    ['mumbaifruits','punefruits','ahmedabadfruits','suratfruits','nagpurfruits','nashikfruits','vadodarafruits','rajkotfruits'],
  South:   ['bengalurufruits','bangalorefruits','chennaifruits','hyderabadfruits','kochifruits','coimbatorefruits','mysorefruits','vizagfruits','maduraifruits'],
  East:    ['kolkatafruits','patnafruits','bhubaneswarfruits','guwahatifruits','ranchifruits','siligurifruits'],
  Central: ['indorefruits','bhopalfruits','raipurfruits','jabalpurfruits','gwaliorfruits'],
  AllIndia:['fruitshopindia','freshfruitsindia','fruitsdelivery','exoticfruitsindia','fruitshop','fruitwala']
};
const TOTAL_TAGS = 12;
const regions = Object.keys(POOL);
const weights = regions.map(() => 0.2 + Math.random());           // random share for each region
const sum = weights.reduce((a, b) => a + b, 0);
const picked = new Set();
regions.forEach((r, i) => {
  const n = Math.max(1, Math.round(TOTAL_TAGS * weights[i] / sum));
  const tags = [...POOL[r]].sort(() => Math.random() - 0.5).slice(0, n);
  tags.forEach(t => picked.add(t));
});
const hashtags = [...picked].sort(() => Math.random() - 0.5).slice(0, TOTAL_TAGS + 2);
return [{ json: { hashtags, mix: regions.map((r, i) => r + ' ' + Math.round(100 * weights[i] / sum) + '%').join(', ') } }];

const names = new Set();
for (const item of $input.all()) {
  const u = item.json.ownerUsername;
  if (u) names.add(u);
}
return [{ json: { usernames: [...names].slice(0, 120) } }];

const shopWords = ['fruit','phal','फल','फळ','ફળ','ফল','பழ','పండ్','ಹಣ್ಣು','പഴ','mandi','juice','shop','store','dukaan','wholesale','delivery'];
const phoneRe = /(?:\+?91[\s-]?)?[6-9]\d{4}[\s-]?\d{5}/;
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  if (!p.username || p.private || p.isPrivate) continue;
  const links = [p.externalUrl, ...(p.externalUrls || []).map(l => l.url || l), ...(p.bioLinks || []).map(l => l.url || l)]
    .filter(Boolean).map(l => String(l).toLowerCase())
    .filter(l => !['maps.app.goo.gl','goo.gl/maps','google.com/maps','maps.google','facebook.com','fb.com','fb.me','instagram.com','youtube.com','youtu.be','threads.net'].some(d => l.includes(d)));
  const isWhatsApp = links.some(l => l.includes('wa.me') || l.includes('whatsapp'));
  const isLinkPage = links.some(l => l.includes('linktr.ee') || l.includes('linkin.bio') || l.includes('bio.link'));
  let linkType;
  if (links.length === 0) linkType = 'No link';
  else if (isWhatsApp) linkType = 'WhatsApp link';
  else if (isLinkPage) linkType = 'Link page - check manually';
  else continue;
  const text = [p.fullName, p.biography, p.businessCategoryName, p.username].join(' ').toLowerCase();
  if (!(shopWords.some(w => text.includes(w)) || p.isBusinessAccount === true)) continue;
  const bioPhone = (p.biography || '').match(phoneRe);
  out.push({ json: {
    platform: 'Instagram', messageUrl: 'https://ig.me/m/' + p.username,
    username: p.username,
    profileUrl: 'https://www.instagram.com/' + p.username + '/',
    name: p.fullName || p.username,
    bio: p.biography || '',
    followers: p.followersCount ?? p.followerCount ?? '',
    linkType,
    link: links[0] || '',
    phone: p.businessPhoneNumber || (bioPhone ? bioPhone[0] : ''),
    city: p.city || (p.location && p.location.city) || '',
    category: p.businessCategoryName || ''
  }});
}
return out.slice(0, 120);

const vendors = $('Prepare pitch request').all();
const keys = ['region','region_reason','language','language_reason','dm_pitch','dm_pitch_english','voice_script','voice_language_code','fit_score','fit_reason'];
return $input.all().map((item, i) => {
  const v = { ...vendors[i].json };
  delete v.claudeRequest;
  const raw = (item.json.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  const usage = item.json.usage || {};
  const p = {};
  for (const k of keys) {
    const m = raw.match(new RegExp('<' + k + '>([\\s\\S]*?)</' + k + '>'));
    p[k] = m ? m[1].trim() : '';
  }
  p.fit_score = Number(p.fit_score) || '';
  if (!p.dm_pitch || !p.voice_script) p.error = 'Could not read pitch';
  return { json: { ...v, ...p, tokensIn: usage.input_tokens, tokensOut: usage.output_tokens, pitchDate: $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd') } };
});

return $('Read pitch').all().filter(i => !i.json.error).map(i => {
  const v = i.json;
  return { json: {
    'Date': v.pitchDate, 'Instagram': v.username, 'Profile link': v.profileUrl, 'Name': v.name, 'City': v.city,
    'Region': v.region || '', 'Language': v.language || '', 'Fit score': v.fit_score || '', 'Fit reason': v.fit_reason || '',
    'Followers': v.followers, 'Phone': v.phone, 'Link in bio': v.link, 'Link type': v.linkType, 'Bio': v.bio,
    'DM pitch': v.dm_pitch || '', 'DM pitch (English)': v.dm_pitch_english || '', 'Voice script': v.voice_script || '',
    'Voice note link': '', 'Status': 'New - awaiting your OK', 'Your notes': '', 'Vendor reply': '', 'Next reply draft': '',
    'Voice language': v.voice_language_code || '', 'Voice speaker': (v.speakerName || 'Ankur') + ' (' + (v.speakerGender || 'male') + ')',
    'Approved on': '', 'Sent on': '', 'Platform': v.platform || 'Instagram', 'Message link': v.messageUrl || ''
  } };
});

const rows = $('Prepare CRM row').all().map(i => i.json).sort((a, b) => (b['Fit score'] || 0) - (a['Fit score'] || 0));
const held = $('Read pitch').all().filter(i => i.json.error).length;
const link = (u, a) => 'https://fruitifyindia.app.n8n.cloud/webhook/fruitify-review?u=' + encodeURIComponent(u) + '&a=' + a + '&k=<APPROVAL_KEY>';
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');
const cards = rows.map((r, n) => `
<div style="border:1px solid #d9e2dc;border-radius:10px;padding:14px;margin:0 0 14px;font-family:Arial,sans-serif">
  <div style="font-size:16px;font-weight:bold">${n + 1}. ${esc(r.Name)} <span style="color:#2e7d4f">(fit ${r['Fit score']}/5)</span></div>
  <div style="color:#555;font-size:13px">${esc(r.Platform || 'Instagram')} &middot; ${esc(r.Region)} &middot; ${esc(r.Language)} &middot; ${esc(r.Followers)} followers ${r.Phone ? '&middot; Phone ' + esc(r.Phone) : ''}</div>
  <p style="margin:8px 0"><a href="${r['Profile link']}">Open ${r.Platform === 'Facebook' ? 'Facebook page' : 'Instagram profile'}</a></p><p style="margin:10px 0"><a href="${link(r.Instagram,'approve')}" style="background:#1f7a4a;color:#fff;padding:9px 18px;border-radius:6px;text-decoration:none;font-weight:bold">Approve</a> &nbsp; <a href="${link(r.Instagram,'skip')}" style="background:#eee;color:#333;padding:9px 18px;border-radius:6px;text-decoration:none">Skip</a></p>
  <div style="background:#f3f8f5;padding:10px;border-radius:8px;font-size:15px">${esc(r['DM pitch'])}</div>
  <div style="color:#666;font-size:12px;margin-top:6px"><b>English:</b> ${esc(r['DM pitch (English)'])}</div>
  <div style="color:#999;font-size:12px;margin-top:6px">Why this account: ${esc(r['Fit reason'])}</div>
</div>`).join('');
const html = `<div style="max-width:680px">
<h2 style="font-family:Arial,sans-serif;color:#1f5f3f">FRUiTIFY - ${rows.length} new vendor pitches for ${$now.setZone('Asia/Kolkata').toFormat('d LLL yyyy')}</h2>
<p style="font-family:Arial,sans-serif;font-size:14px">Nothing has been sent. Tap Approve for each vendor you want to contact today (up to the daily limit) or Skip. From 9:30 am the approved ones are prepared one by one in your Instagram for you to press Send. Full details are in the <a href="https://docs.google.com/spreadsheets/d/1XRt3zf1oAE4jyYYMJgZjU75ZjUylY80yZtsfVuS4iJw/edit">CRM sheet</a>.</p>
<p style="margin:14px 0 22px"><a href="https://fruitifyindia.app.n8n.cloud/webhook/fruitify-review?k=<APPROVAL_KEY>&all=1" style="background:#1f7a4a;color:#fff;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:bold;font-family:Arial,sans-serif;font-size:16px">Approve all (best-fit first, up to the daily limit)</a></p>
${held ? '<p style="font-family:Arial,sans-serif;font-size:13px;color:#a15c00">' + held + ' pitch(es) could not be written properly today and will be retried automatically in the next run.</p>' : ''}${cards}</div>`;
return [{ json: { subject: 'FRUiTIFY: ' + rows.length + ' vendor pitches ready for your OK - ' + $now.setZone('Asia/Kolkata').toFormat('d LLL'), html } }];

// Random cities across all regions for the Facebook Page search
const CITIES = ['Delhi','Gurgaon','Noida','Faridabad','Lucknow','Jaipur','Chandigarh','Ludhiana','Kanpur','Dehradun',
  'Mumbai','Pune','Ahmedabad','Surat','Nagpur','Nashik','Vadodara','Rajkot',
  'Bengaluru','Chennai','Hyderabad','Kochi','Coimbatore','Mysore','Visakhapatnam','Madurai',
  'Kolkata','Patna','Bhubaneswar','Guwahati','Ranchi','Siliguri',
  'Indore','Bhopal','Raipur','Jabalpur','Gwalior'];
const cities = [...CITIES].sort(() => Math.random() - 0.5).slice(0, 4);
return [{ json: { categories: ['fruit shop', 'fresh fruits', 'fruit wala'], locations: cities.map(c => c + ', India'), searchType: 'pages', resultsLimit: 40 } }];

// Works with both the basic page search (name, url, id, description) and the detailed one (title, pageName, website, phone...)
const shopWords = ['fruit','phal','फल','फळ','ફળ','ফল','பழ','పండ్','ಹಣ್ಣು','പഴ','mandi','juice','grocery','vegetable','sabzi','kirana'];
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const id = String(p.pageId || p.facebookId || p.id || '');
  const handle = p.pageName || id;
  if (!handle || seen.has(handle)) continue;
  seen.add(handle);
  const site = String(p.website || '').toLowerCase();
  const isWa = site.includes('wa.me') || site.includes('whatsapp');
  const isSocial = !site || ['facebook.com','instagram.com','linktr.ee','youtube.com','goo.gl/maps','google.com/maps'].some(d => site.includes(d));
  if (!isWa && !isSocial) continue;                         // has a real website - skip
  const name = p.title || p.name || handle;
  const bio = [p.description, p.info, p.about_me].filter(Boolean).join(' ');
  const text = [name, (p.categories || []).join(' '), bio].join(' ').toLowerCase();
  if (!shopWords.some(w => text.includes(w))) continue;
  const city = p.address || (decodeURIComponent(String(p.facebookUrl || '')).match(/q=[^&]*?(?:shop|fruits|wala) ([^,&]+)/i) || [])[1] || '';
  out.push({ json: {
    platform: 'Facebook', username: 'fb:' + handle,
    profileUrl: p.pageUrl || p.url || ('https://www.facebook.com/' + handle),
    messageUrl: 'https://m.me/' + (p.pageName || id),
    name, bio: bio.slice(0, 600), followers: p.followers ?? p.likes ?? '',
    linkType: isWa ? 'WhatsApp link' : (site ? 'No website' : 'No website listed'), link: p.website || '',
    phone: p.phone || '', city, category: (p.categories || []).join(', ')
  } });
}
return out.slice(0, 40);
